async () => {
 const checks=[],check=(name,pass)=>{checks.push({name,pass:!!pass});if(!pass)throw Error(name);};
 const settle=()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
 const content=()=>document.querySelector('main').textContent;
 const metrics=()=>[...document.querySelectorAll('.learning-overview-metrics>div')].map(r=>[r.querySelector('span').textContent,r.querySelector('b').textContent]);
 const navWorks=()=>[...document.querySelectorAll('.learning-subnav a')].every(a=>document.querySelector(a.getAttribute('href')));
 const reload=()=>[...document.querySelectorAll('a')].filter(a=>a.textContent==='Reload learning page');
 const oneReadEach=()=>JSON.stringify(window.qa.calls)===JSON.stringify(['auth','progress','portfolio','profile','enrolments']);
 await window.qa.render(['progress']);
 check('partial outage has one explicit reload action',reload().length===1&&reload()[0].getAttribute('href')==='/my-learning');
 check('unavailable saved count is not zero',metrics().some(([k,v])=>k==='Saved modules'&&v==='Unavailable'));
 check('available course launch retains exact workbook',document.querySelector('.enrolled-course-card a.primary-button')?.getAttribute('href')==='/learn/synthetic-course/workbook-one');
 check('actual portfolio retains saved note and revision',content().includes('Synthetic saved note')&&content().includes('Synthetic revision'));
 check('all local section links have real targets',navWorks());
 check('missing saved data does not pretend collection is empty',!content().includes('No saved modules yet'));
 check('partial options notice explains incomplete choices',content().includes('Some saved or enrolled resource choices are unavailable.'));
 check('each service loads once after authentication',oneReadEach());
 check('no desktop horizontal overflow',document.documentElement.scrollWidth<=innerWidth);
 const note=document.querySelector('.portfolio-compose');note.open=true;await settle();
 const title=note.querySelector('input[name="title"]'),body=note.querySelector('textarea[name="body"]');
 title.value='Synthetic unsaved note';title.dispatchEvent(new Event('input',{bubbles:true}));body.value='A draft retained during partial availability.';body.dispatchEvent(new Event('input',{bubbles:true}));await settle();
 check('static Atlas and loaded course choices remain available',!!note.querySelector('option[value="atlas::ct-head"]')&&!!note.querySelector('option[value="course::synthetic-course"]'));
 const dirty=new Event('beforeunload',{cancelable:true});window.dispatchEvent(dirty);check('existing unload guard protects unsaved note on reload',dirty.defaultPrevented);
 note.open=false;note.open=true;await settle();check('disclosure retains draft while other section unavailable',title.value==='Synthetic unsaved note'&&body.value==='A draft retained during partial availability.');
 note.querySelector('form').reset();title.dispatchEvent(new Event('input',{bubbles:true}));const clean=new Event('beforeunload',{cancelable:true});window.dispatchEvent(clean);check('cleared draft does not block unload',!clean.defaultPrevented);
 await window.qa.render(['portfolio']);check('failed portfolio has unavailable metrics',metrics().filter(([k])=>['Reviews','Completions'].includes(k)).every(([,v])=>v==='Unavailable'));
 check('no forms or fictitious empty notes when portfolio unavailable',!document.querySelector('.portfolio-form')&&!content().includes('No private notes yet.'));
 check('failed portfolio section navigation remains valid',navWorks()&&!!document.querySelector('.learning-subnav a[href="#portfolio-unavailable"]'));
 check('saved Atlas remains navigable',document.querySelector('.progress-card')?.getAttribute('href')==='/atlas/ct-head');
 await window.qa.render(['enrolments']);check('enrolment outage never grants workbook link',[...document.querySelectorAll('a')].every(a=>!a.getAttribute('href').startsWith('/learn/')));
 check('saved course falls back to catalogue without claimed access',[...document.querySelectorAll('.progress-card')].some(a=>a.getAttribute('href')==='/courses'));
 check('existing private note persists with no enrolments',content().includes('Synthetic saved note'));
 await window.qa.render(['profile']);check('missing profile is not treated as incomplete onboarding',content().includes('Profile unavailable.')&&!content().includes('Setup required')&&!content().includes('Complete profile'));
 check('account and signout remain available',!!document.querySelector('a[href="/account"]')&&!!document.querySelector('a[href="/synthetic-sign-out"]'));
 await window.qa.render(['progress','portfolio','profile','enrolments']);check('combined outage still has only one reload',reload().length===1);
 check('combined outage offers Atlas and course destinations',!!document.querySelector('a[href="/atlas"]')&&!!document.querySelector('a[href="/courses"]'));
 check('raw service errors are never displayed',!content().includes('D1_ERROR')&&!content().includes('Network connection lost'));
 check('combined outage is not four empty collections',metrics().every(([,v])=>v==='Unavailable')&&!content().includes('No saved modules yet'));
 await window.qa.render([],true);check('successful empty collections retain truthful states',content().includes('No course enrolments yet')&&content().includes('No saved modules yet')&&metrics().some(([k,v])=>k==='Saved modules'&&v==='0'));
 check('clean loaded page has no outage notice',!document.querySelector('.learning-availability-notice'));
 await window.qa.render(['progress']);check('no implicit retries or background requests',oneReadEach()&&window.qa.fetches.length===0);
 check('actual React has no runtime errors',window.qa.errors.length===0);
 reload()[0].focus();check('reload is keyboard-focusable',document.activeElement===reload()[0]);
 window.qa.checks.push(...checks);
 return {passing:true,checks,assertions:checks.length,width:innerWidth,height:innerHeight,errors:window.qa.errors,scope:'Actual page, portfolio, helper modules and CSS; synthetic auth/data services and Next Link adapter. Synthetic beforeunload event verifies guard cancellation without a native dialog. No backend or account acceptance.'};
}
